#!/usr/bin/env bash
# Tutos parcours pour les visiteurs et les membres : 5 tutos, leurs fiches dans le guide, leurs tests.
# Prérequis : apply-docs-migrator-quiet.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-tutos-membres.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/tours/TourOverlay.tsx" 2>/dev/null | grep -qF "OPTIONAL_WAIT_MS"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Et Prisma n’y vérifie plus" "apps/web/content/docs/dev/infrastructure/l-image-docker.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-migrator-quiet.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/guide/index.mdx" "apps/web/src/app/(public)/documents/page.tsx" "apps/web/src/app/(public)/profil/edit/page.tsx" "apps/web/src/app/(public)/profil/page.tsx" "apps/web/src/app/auth/forgot-password/page.tsx" "apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" "apps/web/src/features/app-shell/Header.tsx" "apps/web/src/features/contact/ContactForm.tsx" "apps/web/src/features/docs/lib/docs.navigation.ts" "apps/web/src/features/member-documents/DocumentReaderPanel.tsx" "apps/web/src/features/tours/TourOverlay.tsx" "apps/web/src/features/tours/tour.registry.ts" "apps/web/src/features/tours/tour.types.ts" "e2e/prepare.mjs")
EXPECT=("ab719d06401a:apps/web/content/docs/guide/index.mdx" "614418034d2c:apps/web/src/app/(public)/documents/page.tsx" "152c60cdba19:apps/web/src/app/(public)/profil/edit/page.tsx" "064dc580192c:apps/web/src/app/(public)/profil/page.tsx" "703ff74cd7f7:apps/web/src/app/auth/forgot-password/page.tsx" "fd40be6dd79f:apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" "38fd60ed1909:apps/web/src/features/app-shell/Header.tsx" "89c57b77a501:apps/web/src/features/contact/ContactForm.tsx" "63d4ce02d3d3:apps/web/src/features/docs/lib/docs.navigation.ts" "c4c45388bb16:apps/web/src/features/member-documents/DocumentReaderPanel.tsx" "a474ea504a05:apps/web/src/features/tours/TourOverlay.tsx" "0ba09b4e4d26:apps/web/src/features/tours/tour.registry.ts" "654506c5b660:apps/web/src/features/tours/tour.types.ts" "b6858a217673:e2e/prepare.mjs")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/guide/contacter-le-club.mdx" "apps/web/content/docs/guide/decouvrir-le-site.mdx" "apps/web/content/docs/guide/mes-documents.mdx" "apps/web/content/docs/guide/mon-profil.mdx" "apps/web/content/docs/guide/mot-de-passe-oublie.mdx" "apps/web/src/features/tours/definitions/membre.contacter-le-club.ts" "apps/web/src/features/tours/definitions/membre.documents.ts" "apps/web/src/features/tours/definitions/membre.profil.ts" "apps/web/src/features/tours/definitions/public.decouvrir-le-site.ts" "apps/web/src/features/tours/definitions/public.mot-de-passe-oublie.ts" "e2e/tutos-parcours.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "OPTIONAL_WAIT_MS" "apps/web/src/features/tours/TourOverlay.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

